// lib/theme-menu.ts
var names = { light: "ライト", dark: "ダーク", system: "OS に従う" };
function mount() {
  const theme = window.hergyTheme;
  const control = document.querySelector(".theme-control");
  if (!theme || !control)
    return;
  const trigger = control.querySelector(".theme-trigger");
  const panel = control.querySelector(".theme-panel");
  const menu = control.querySelector('[role="menu"]');
  const notice = control.querySelector('[role="status"]');
  const items = [...menu.querySelectorAll('[role="menuitemradio"]')];
  let opened = false;
  function update() {
    const { mode, failed } = theme.state;
    trigger.disabled = false;
    trigger.dataset.mode = mode;
    trigger.title = `明暗を選ぶ（現在: ${names[mode]}）`;
    trigger.setAttribute("aria-label", trigger.title);
    trigger.setAttribute("aria-expanded", String(opened));
    for (const item of items)
      item.setAttribute("aria-checked", String(item.dataset.mode === mode));
    menu.hidden = !opened;
    notice.hidden = !failed;
    panel.hidden = !opened && !failed;
  }
  function close(returnFocus = false) {
    opened = false;
    update();
    if (returnFocus)
      trigger.focus();
  }
  function open() {
    opened = true;
    update();
    items.find((item) => item.dataset.mode === theme.state.mode)?.focus();
  }
  trigger.addEventListener("click", () => {
    if (opened)
      close();
    else
      open();
  });
  trigger.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation();
      open();
    }
  });
  for (const item of items)
    item.addEventListener("click", () => {
      const mode = item.dataset.mode;
      if (mode !== "light" && mode !== "dark" && mode !== "system")
        return;
      theme.choose(mode);
      close(true);
    });
  control.addEventListener("keydown", (event) => {
    if (!opened || event.altKey || event.ctrlKey || event.metaKey || event.isComposing)
      return;
    const at = items.indexOf(document.activeElement);
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close(true);
    } else if (event.key === "Tab")
      close();
    else if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
      event.preventDefault();
      const index = event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : (at + (event.key === "ArrowDown" ? 1 : -1) + items.length) % items.length;
      items[index].focus();
    }
  });
  document.addEventListener("click", (event) => {
    if (!control.contains(event.target))
      close();
  });
  control.addEventListener("focusout", (event) => {
    if (!control.contains(event.relatedTarget))
      close();
  });
  window.addEventListener("hergy:theme", update);
  update();
}
mount();
